def window_summary(events: list[tuple[int,int]], start: int, end: int, limit: int) -> tuple[int,int] | None:
    if start>end or limit<0: return None
    a=sorted(((t,v,i) for i,(t,v) in enumerate(events) if start<=t<end),key=lambda x:(x[0],x[2]))
    a=a[-limit:] if limit else []
    return len(a),sum(x[1] for x in a)
